"""Record real WLED HTTP and optional passive USB serial diagnostics; never change device state."""

import argparse
import datetime
import ipaddress
import json
from pathlib import Path
import threading
import time
import urllib.error
import urllib.request


# AI: below section was generated by an AI
def timestamp():
    """Use UTC in saved records so serial and HTTP observations can be correlated."""
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


class Recorder:
    """Flush every record to disk so a board crash or interrupted capture loses little evidence."""

    def __init__(self, folder):
        self.folder = folder
        folder.mkdir(parents=True, exist_ok=True)
        self.lock = threading.Lock()
        self.output = (folder / "events.jsonl").open("a", encoding="utf-8")
        self.uptimes = {}
        self.config_text = None

    def emit(self, event, **values):
        record = {"timestampUtc": timestamp(), "event": event, **values}
        with self.lock:
            self.output.write(json.dumps(record, ensure_ascii=False) + "\n")
            self.output.flush()
        print(json.dumps(record, ensure_ascii=False), flush=True)

    def sample(self, host, path, role):
        """Query only fixed read-only endpoints; do not follow local device redirects."""
        started = time.monotonic()
        try:
            class NoRedirect(urllib.request.HTTPRedirectHandler):
                def redirect_request(self, req, fp, code, msg, headers, newurl):
                    return None

            opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect())
            request = urllib.request.Request("http://" + host + path, headers={"Connection": "close"})
            with opener.open(request, timeout=3) as response:
                raw = response.read(65537)
                if len(raw) > 65536:
                    raise ValueError("Response exceeds 64 KiB")
                data = json.loads(raw)
            if not isinstance(data, dict):
                raise ValueError("Expected a JSON object")
            if path == "/json/info":
                data = {key: data.get(key) for key in (
                    "ver", "ip", "uptime", "freeheap", "leds", "live", "lm", "lip", "wifi")}
                # Avoid collecting MAC addresses/BSSID; only radio health matters here.
                data["wifi"] = {key: (data.get("wifi") or {}).get(key) for key in ("rssi", "signal", "channel", "ap")}
                uptime = data.get("uptime")
                previous = self.uptimes.get(host)
                if isinstance(uptime, (int, float)):
                    if previous is not None and uptime < previous:
                        self.emit("uptime_decreased", host=host, previous=previous, current=uptime)
                    self.uptimes[host] = uptime
            elif path == "/json/ledwall":
                config = data.get("config")
                if isinstance(config, dict):
                    text = json.dumps(config, indent=2, ensure_ascii=False) + "\n"
                    if text != self.config_text:
                        (self.folder / "layout-latest.json").write_text(text, encoding="utf-8")
                        self.config_text = text
                data = {"status": data.get("status"), "controllers": (config or {}).get("controllers")}
            elif path.endswith("/devices") and not isinstance(data.get("devices"), list):
                raise ValueError("Wrong discovery response: expected devices array")
            self.emit("http", role=role, host=host, path=path,
                      elapsedMs=round((time.monotonic() - started) * 1000), data=data)
        except (OSError, ValueError) as error:
            self.emit("http_error", role=role, host=host, path=path,
                      elapsedMs=round((time.monotonic() - started) * 1000), error=str(error))


def capture_serial(port_name, recorder, stopped, query_info=False):
    """Listen at 115200 baud with DTR/RTS low; send no serial commands or reset pulses."""
    try:
        import serial
        port = serial.Serial(port=None, baudrate=115200, timeout=0.5)
        port.dtr = False
        port.rts = False
        port.port = port_name
        port.open()
    except (ImportError, OSError) as error:
        recorder.emit("serial_open_failed", port=port_name, error=str(error))
        return
    recorder.emit("serial_open", port=port_name, baud=115200, dtr=False, rts=False)
    pending = bytearray()
    next_query = 0.0
    try:
        with (recorder.folder / "serial.log").open("a", encoding="utf-8") as output:
            output.write("\nCAPTURE_START " + timestamp() + "\n")
            while not stopped.is_set():
                if query_info and time.monotonic() >= next_query:
                    port.write(b'{"v":true}\n')
                    port.flush()
                    next_query = time.monotonic() + 10
                block = port.read(min(max(port.in_waiting, 1), 4096))
                if not block:
                    continue
                pending.extend(block)
                # Bound unterminated serial messages while retaining every received byte.
                while b"\n" in pending or len(pending) >= 8192:
                    if b"\n" in pending:
                        line, _, pending = pending.partition(b"\n")
                    else:
                        line, pending = pending[:8192], pending[8192:]
                    text = line.decode("utf-8", "replace").rstrip("\r")
                    output.write(timestamp() + " " + text + "\n")
                    output.flush()
                    if text.startswith("{"):
                        try:
                            message = json.loads(text)
                            info = message.get("info")
                            if isinstance(info, dict):
                                recorder.emit("serial_info", port=port_name, data={
                                    "uptime": info.get("uptime"), "freeheap": info.get("freeheap"),
                                    "wifi": {key: info.get("wifi", {}).get(key) for key in ("rssi", "signal", "sleep")},
                                    "ledwall": info.get("ledwall")})
                        except ValueError:
                            pass
                    # Keep terminal output compact; all driver error repetitions remain in serial.log.
                    if any(word in text.lower() for word in ("guru", "panic", "backtrace", "brownout", "watchdog", "rst:", "[ledwall]")):
                        recorder.emit("serial", port=port_name, text=text)
            if pending:
                output.write(timestamp() + " " + pending.decode("utf-8", "replace") + "\n")
    except OSError as error:
        recorder.emit("serial_error", port=port_name, error=str(error))
    finally:
        port.close()
        recorder.emit("serial_closed", port=port_name)


def main():
    """Monitor real boards until the duration expires or Ctrl+C; never substitute generated devices."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--master", type=ipaddress.IPv4Address, required=True)
    parser.add_argument("--slave", type=ipaddress.IPv4Address, action="append", default=[])
    parser.add_argument("--serial-port", help="Optional master USB serial port, e.g. COM8")
    parser.add_argument("--serial-info", action="store_true", help="Also request native USB informational JSON every 10 seconds")
    parser.add_argument("--duration", type=int, default=300, help="Seconds; 0 collects one HTTP cycle")
    parser.add_argument("--interval", type=int, default=10, help="Minimum seconds between HTTP cycles")
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    if args.duration < 0 or args.interval < 5:
        parser.error("duration must be nonnegative and interval at least 5 seconds")
    if args.serial_info and not args.serial_port:
        parser.error("--serial-info requires --serial-port")
    folder = args.output or Path(".pio/ledwall-diagnostics") / datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
    recorder = Recorder(folder)
    stopped = threading.Event()
    thread = None
    if args.serial_port:
        thread = threading.Thread(target=capture_serial, args=(args.serial_port, recorder, stopped, args.serial_info), daemon=True)
        thread.start()
    recorder.emit("capture_start", master=str(args.master), slaves=list(map(str, args.slave)), output=str(folder.resolve()))
    started = time.monotonic()
    cycle = 0
    try:
        while True:
            cycle_start = time.monotonic()
            recorder.sample(str(args.master), "/json/info", "master")
            recorder.sample(str(args.master), "/json/ledwall", "master")
            if cycle % 3 == 0:
                recorder.sample(str(args.master), "/json/ledwall/devices", "master")
                for host in args.slave:
                    recorder.sample(str(host), "/json/info", "slave")
            cycle += 1
            if not args.duration or time.monotonic() - started >= args.duration:
                break
            stopped.wait(max(0, args.interval - (time.monotonic() - cycle_start)))
    except KeyboardInterrupt:
        pass
    finally:
        stopped.set()
        if thread:
            thread.join(timeout=2)
        recorder.emit("capture_end", cycles=cycle)
        recorder.output.close()


if __name__ == "__main__":
    main()
# AI: end
